\end{tikzpicture}\end{center}
\begin{enumerate}
\item На участке $CD$ модуль скорости тела увеличивается.
\item В точке $A$ проекция ускорения тела на ось $Ox$ отрицательна.
\item На участке $BC$ модуль скорости тела увеличивается.
\item В точке $B$ ускорение тела и его скорость направлены в противоположные стороны.
\item В точке $B$ проекция скорости тела на ось $Ox$ отрицательна.
\end{enumerate}

На рисунке приведены графики зависимости координаты $x$ от времени $t$ для двух точечных тел $1$ и $2$, движущихся по прямой, вдоль которой направлена ось $Ox$. Масса каждого тела равна $0{,}5\,\text{кг}$.
\begin{center}\begin{tikzpicture}[x=.25cm,y=.5cm,>=stealth]
\draw[thin,black!65,xstep=2,ystep=1] (0,0) grid (20,8);
\draw[->] (0,0)--(22,0) node[right] {$t,\,\text{с}$};
\draw[->] (0,0)--(0,9) node[above] {$x,\,\text{м}$};
\foreach \x in {0,4,8,12,16,20} \node[below] at (\x,0) {$\x$};
\foreach \y in {2,4,6} \node[left] at (0,\y) {$\y$};
\draw[very thick] (0,.5)--(20,5.5);\node at (12,3.9) {$1$};
\draw[very thick,domain=0:19.2,samples=60] plot (\x,{1+(\x-10)^2/16});\node at (17,1.7) {$2$};
\end{tikzpicture}\end{center}
\begin{enumerate}
\item Проекция скорости тела $2$ на ось $Ox$ в момент времени $4\,\text{с}$ отрицательна.
\item Тело $1$ движется со скоростью $3\,\text{м}/\text{с}$.
\item Проекция ускорения тела $2$ на ось $Ox$ отрицательна.
\item Кинетическая энергия тела $1$ в момент времени $10\,\text{с}$ равна $2{,}25\,\text{Дж}$.
\item Расстояние между точками встречи тел равно $3\,\text{м}$.
\end{enumerate}

На рисунке приведены зависимости координат $x$ двух грузов $1$ и $2$ от времени $t$ в процессе их малых колебаний на гладкой горизонтальной плоскости. Грузы имеют одинаковую массу $m$ и прикреплены к пружинам жёсткостью $k_{1}$ (груз $1$) и жёсткостью $k_{2}$ (груз $2$). Колебания груза $1$ обозначены сплошной линией, груза $2$ – пунктиром.
\begin{center}\begin{tikzpicture}[x=.96cm,y=.8cm,>=stealth]
\foreach \q in {0,1,2,3,4,5,6} \draw[thin,black!65] (\q,-2)--(\q,2);
\draw[thin,black!65] (0,2)--(6,2) (0,-2)--(6,-2);
\foreach \h in {-1.5,-1,-.5,.5,1,1.5} \draw[thin,black!65] (0,\h)--(1.1,\h) (1.4,\h)--(2,\h) (2.8,\h)--(3.5,\h) (4,\h)--(5,\h) (5.3,\h)--(6,\h);
\draw[->] (0,0)--(6.6,0) node[right] {$t,\,\text{с}$};
\draw[->] (0,-2)--(0,2.7) node[above] {$x,\,\text{см}$};
\foreach \x in {1,2,3,4,5,6} \node[below] at (\x,0) {$\x$};
\foreach \y in {-2,-1,0,1,2} \node[left] at (0,\y) {$\y$};
\draw[very thick,domain=0:6,samples=100] plot (\x,{2*sin(90*\x)});
\draw[thick,dashed,domain=0:6,samples=100] plot (\x,{cos(90*(\x-.25))});
\node at (5.8,1.85) {$1$};\node at (3.2,1.0) {$2$};
\end{tikzpicture}\end{center}
\begin{enumerate}
\item Периоды колебаний грузов одинаковы.
\item Максимальные потенциальные энергии деформированных пружин одинаковы.
\item Жёсткость пружины $k_{1}$ меньше жёсткости пружины $k_{2}$.
\item Амплитуды колебаний грузов одинаковы.
\item Максимальная кинетическая энергия груза $1$ в четыре раза больше, чем максимальная кинетическая энергия груза $2$.
\end{enumerate}

В инерциальной системе отсчёта вдоль оси $Ox$ движется тело массой $20\,\text{кг}$. На рисунке приведён график зависимости проекции скорости $V_{x}$ этого тела от времени $t$.
\begin{center}
\begin{tikzpicture}[x=0.06cm,y=0.6cm,>=stealth]
