\draw[->] (0,0)--(110,0) node[right] {$t,\,\text{с}$};
\draw[->] (0,0)--(0,5) node[above] {$v_x,\,\text{м}/\text{с}$};

\node[below] at (10,0) {$10$};
\node[below] at (20,0) {$20$};
\node[below] at (30,0) {$30$};
\node[below] at (40,0) {$40$};
\node[below] at (50,0) {$50$};
\node[below] at (60,0) {$60$};
\node[below] at (70,0) {$70$};
\node[below] at (80,0) {$80$};
\node[below] at (90,0) {$90$};
\node[below] at (100,0) {$100$};
\node[left] at (0,0) {$0$};
\node[left] at (0,1) {$1$};
\node[left] at (0,2) {$2$};
\node[left] at (0,3) {$3$};
\node[left] at (0,4) {$4$};
\draw[very thick] (0,0)--(20,4)--(60,4)--(80,3)--(100,0);
\end{tikzpicture}
\end{center}
\begin{enumerate}
